# Based on Cortex-A78 Software Optimization Guide
# s3.13 FP load instructions

# Load vector reg, literal, S/D/Q forms
ldr	s0, #4
ldr	d0, #4
ldr	q0, #4

# Load vector reg, unscaled immed
ldur	b0, [x1, #1]
ldur	h0, [x1, #1]
ldur	s0, [x1, #1]
ldur	d0, [x1, #1]
ldur	q0, [x1, #1]

# Load vector reg, immed post-index
ldr	b0, [x1], #1
ldr	h0, [x1], #1
ldr	s0, [x1], #1
ldr	d0, [x1], #1
ldr	q0, [x1], #1

# Load vector reg, immed pre-index
ldr	b0, [x1, #1]!
ldr	h0, [x1, #1]!
ldr	s0, [x1, #1]!
ldr	d0, [x1, #1]!
ldr	q0, [x1, #1]!

# Load vector reg, unsigned immed
ldr	b0, [x1, #64]
ldr	h0, [x1, #64]
ldr	s0, [x1, #64]
ldr	d0, [x1, #64]
ldr	q0, [x1, #64]

# Load vector reg, register offset, LDR basic
ldr	b0, [x1, x2]
ldr	h0, [x1, x2]
ldr	s0, [x1, x2]
ldr	d0, [x1, x2]
ldr	q0, [x1, x2]

# Load vector reg, register offset, scale, S/D-form
ldr	s0, [x1, x2, lsl #2]
ldr	d0, [x1, x2, lsl #3]

# Load vector reg, register offset, scale, H/Q-form
ldr	h0, [x1, x2, lsl #1]
ldr	q0, [x1, x2, lsl #4]

# Load vector reg, register offset, extend
ldr	s0, [x1, x2, sxtx]
ldr	d0, [x1, x2, sxtx]
ldr	h0, [x1, x2, sxtx]
ldr	q0, [x1, x2, sxtx]

# Load vector reg, register offset, extend, scale, S/D-form
ldr	s0, [x1, x2, sxtx #2]
ldr	d0, [x1, x2, sxtx #3]

# Load vector reg, register offset, extend, scale, H/Q-form
ldr	h0, [x1, x2, sxtx #1]
ldr	q0, [x1, x2, sxtx #4]

# Load vector pair, immed offset, S/D-form
ldp	s0, s1, [x2, #16]
ldp	d0, d1, [x2, #16]
ldnp	s0, s1, [x2, #16]
ldnp	d0, d1, [x2, #16]

# Load vector pair, immed offset, Q-form
ldp	q0, q1, [x2, #16]

# Load vector pair, immed post-index, S/D-form
ldp	s0, s1, [x2], #16
ldp	d0, d1, [x2], #16

# Load vector pair, immed post-index, Q-form
ldp	q0, q1, [x2], #16

# Load vector pair, immed pre-index, S/D-form
ldp	s0, s1, [x2, #16]!
ldp	d0, d1, [x2, #16]!

# Load vector pair, immed pre-index, Q-form
ldp	q0, q1, [x2, #16]!

